+    public void StopPolling()
+    {
+        lock (_lock)
+        {
+            _subscriberCount--;
+            if (_subscriberCount <= 0)
+            {
+                _subscriberCount = 0;
+                _timer?.Dispose();
+                _timer = null;
+            }
+        }
+    }
